window.QUIZ_REG = window.QUIZ_REG || {};
window.QUIZ_REG["Aptis_Listening_P1_De02"] = {"slug": "Aptis_Listening_P1_De02", "title": "APTIS LISTENING PART 1 – ĐỀ 02 (49 câu)", "items": [{"id": 1, "question": "A saleswoman is talking to a customer about a house. What is not original?", "options": [{"key": "A", "text": "Floor"}, {"key": "B", "text": "Furniture"}, {"key": "C", "text": "Architecture"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q052.mp3", "transcript": "I'm so glad you're interested in this beautiful property this house was built in the 1920s and has maintained much of its original charm the hardwood floors you see here are completely original and they've been carefully preserved over the years the same goes for the architecture those High ceilings and detailed moldings are a testament to the craftsmanship of that era however the furniture you see isn't original it was replaced a few years ago to give the home a more modern functional feel but don't worry the updates blend well with the classic features giving you the best of both worlds historic charm with modern comfort", "translation": "Tôi rất vui vì bạn quan tâm đến bất động sản xinh đẹp này. Ngôi nhà này được xây dựng vào những năm 1920 và vẫn giữ được nhiều nét quyến rũ ban đầu. Sàn gỗ cứng mà bạn thấy ở đây hoàn toàn nguyên bản và chúng đã được bảo quản cẩn thận qua nhiều năm. Về kiến trúc, trần nhà cao và các đường gờ chi tiết là minh chứng cho sự khéo léo của thời đại đó tuy nhiên đồ nội thất bạn nhìn thấy không phải là nguyên bản, nó đã được thay thế vài năm trước để mang lại cho ngôi nhà cảm giác chức năng hiện đại hơn nhưng đừng lo lắng, những cải tiến này kết hợp tốt với các tính năng cổ điển mang lại cho bạn những gì tốt nhất của cả hai thế giới quyến rũ lịch sử với tiện nghi hiện đại", "question_vi": "Một nhân viên bán hàng đang nói chuyện với khách hàng về một ngôi nhà. Cái gì không phải là bản gốc?", "answer_guess": true, "extra": ["Ceilings", "Moldings"], "audio": "data/Aptis_Listening_P1_De02/audio/q01.mp3"}, {"id": 2, "question": "Listen to the announcement from a travel agent representative. Why is the air travel cancelled?", "options": [{"key": "A", "text": "Engine failure"}, {"key": "B", "text": "Poor weather conditions"}, {"key": "C", "text": "Delay at transit spot"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q053.mp3", "transcript": "Good afternoon everyone I'd like to start by saying that we're doing everything we can to assist you with your travel plans today unfortunately due to poor weather conditions our flight has been canceled I know this isn't the news you were hoping for but your safety comes first that said we do have Alternatives available the train services are still running and buses are also operating so you have options to continue your journey if you'd like to explore these Alternatives please come see us and will help with the arrangements thank you for your patience and understanding", "translation": "Xin chào mọi người. Tôi muốn bắt đầu bằng cách nói rằng chúng tôi đang làm mọi thứ có thể để hỗ trợ bạn trong kế hoạch du lịch hôm nay, thật không may do điều kiện thời tiết xấu, chuyến bay của chúng tôi đã bị hủy. Tôi biết đây không phải là tin tức mà bạn mong đợi nhưng sự an toàn của bạn là trên hết vì chúng tôi có sẵn các Giải pháp thay thế, các dịch vụ xe lửa vẫn đang chạy và xe buýt cũng đang hoạt động nên bạn có các lựa chọn để tiếp tục hành trình của mình nếu bạn muốn khám phá các Giải pháp thay thế này, vui lòng đến gặp chúng tôi và sẽ giúp sắp xếp, cảm ơn vì sự kiên nhẫn và thông cảm của bạn", "question_vi": "Nghe thông báo từ đại diện đại lý du lịch. Vì sao chuyến bay bị hủy?", "answer_guess": true, "extra": ["Pilot illness", "Strike by staff"], "audio": "data/Aptis_Listening_P1_De02/audio/q02.mp3"}, {"id": 3, "question": "A tour guide is talking about the group's traveling schedule. Where will the group wait for the bus?", "options": [{"key": "A", "text": "by the hotel's side entrance"}, {"key": "B", "text": "behind the hotel's main entrance"}, {"key": "C", "text": "by the hotel's main entrance"}], "answer": "C", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q054.mp3", "transcript": "Good morning everyone let me walk you through today's schedule first will start the day at 9 a.m. with a visit to the city museum where you'll have about 2 hours to explore the exhibits after that at 12:30 p.m. will head to the Central Park for a picnic lunch and a relaxing stroll around 3:00 p.m. will make our way to the Old Town Market where you can shop for souvenirs and enjoy some local treats will wrap up our activities by 6:00 p.m. giving you a little free time back at the hotel finally at 8:00 p.m. will meet at the hotels main entrance to catch the bus to the airport make sure to be on time and we'll head to the airport together", "translation": "Chào buổi sáng mọi người, hãy để tôi hướng dẫn bạn lịch trình ngày hôm nay. Đầu tiên, ngày mới sẽ bắt đầu lúc 9 giờ sáng với chuyến tham quan bảo tàng thành phố, nơi bạn sẽ có khoảng 2 giờ để khám phá các cuộc triển lãm sau đó lúc 12:30 trưa. sẽ đến Công viên Trung tâm để ăn trưa dã ngoại và đi dạo thư giãn vào khoảng 3 giờ chiều. sẽ đến Chợ Phố Cổ, nơi bạn có thể mua quà lưu niệm và thưởng thức một số món ăn địa phương. Hoạt động của chúng tôi sẽ kết thúc trước 6 giờ chiều. cho bạn chút thời gian rảnh rỗi để quay lại khách sạn vào lúc 8 giờ tối. sẽ gặp nhau ở cổng chính của khách sạn để bắt xe buýt đến sân bay, đảm bảo đến đúng giờ và chúng ta sẽ cùng nhau đến sân bay", "question_vi": "Một hướng dẫn viên du lịch đang nói về lịch trình du lịch của nhóm. Nhóm sẽ đợi xe buýt ở đâu?", "answer_guess": true, "extra": ["at the bus station", "in the hotel lobby"], "audio": "data/Aptis_Listening_P1_De02/audio/q03.mp3"}, {"id": 4, "question": "Pierre and Emma are talking together about the picnic on the weekend. What will they bring to the picnic?", "options": [{"key": "A", "text": "Drinks"}, {"key": "B", "text": "Salads"}, {"key": "C", "text": "Food"}], "answer": "C", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q055.mp3", "transcript": "Hey Emma are you ready for the picnic this weekend definitely I'm really looking forward to it do you know what everyone's bringing yeah I spoke with a few people Sarah's bringing cups and bowls and Tom said he'll take care of drinks he's got some lemonade and iced tea ready sounds great I think Clara mentioned she's making a fruit salad right now so what should we bring that's a good idea how about we prepare some chicken and french fries perfect this picnic is going to be amazing", "translation": "Này Emma, ​​bạn đã sẵn sàng cho chuyến dã ngoại cuối tuần này chưa chắc chắn Tôi rất mong chờ nó bạn có biết mọi người sẽ mang gì không ừ tôi đã nói chuyện với một vài người Sarah đang mang cốc và bát và Tom nói anh ấy sẽ lo đồ uống anh ấy có sẵn một ít nước chanh và trà đá nghe hay lắm Tôi nghĩ Clara đã nói rằng cô ấy đang làm salad trái cây ngay bây giờ vậy chúng ta nên mang theo gì đây là một ý kiến ​​hay.", "question_vi": "Pierre và Emma đang cùng nhau trò chuyện về chuyến dã ngoại cuối tuần. Họ sẽ mang theo những gì khi đi dã ngoại?", "answer_guess": true, "extra": ["Cups and bowls", "Fruit salad"], "audio": "data/Aptis_Listening_P1_De02/audio/q04.mp3"}, {"id": 5, "question": "Two friends are talking about their school days. What was the woman good at?", "options": [{"key": "A", "text": "Swimming"}, {"key": "B", "text": "Plays football"}, {"key": "C", "text": "Running"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q056.mp3", "transcript": "Hey do you remember our old school days you were on the football team right yeah I played for the school team those were some of my best memories we even want a few medals what about you were you into football but I was pretty good at swimming my team also brought home some medals it was such a good feeling we really had our own things going on back then", "translation": "Này, bạn có nhớ ngày xưa của chúng ta không, bạn từng ở trong đội bóng đá phải không, tôi chơi cho đội bóng của trường, đó là một trong những kỷ niệm đẹp nhất của tôi, chúng tôi thậm chí còn muốn có một vài huy chương, còn bạn thì sao nếu bạn thích bóng đá nhưng tôi bơi khá giỏi, đội của tôi cũng mang về nhà một số huy chương, đó là một cảm giác tuyệt vời khi chúng tôi thực sự có những điều riêng của mình hồi đó", "question_vi": "Hai người bạn đang kể về thời đi học của họ. Người phụ nữ đó giỏi việc gì?", "answer_guess": true, "extra": ["Tennis", "Singing"], "audio": "data/Aptis_Listening_P1_De02/audio/q05.mp3"}, {"id": 6, "question": "A tour guide is talking about birds' behaviors. What do birds do in the winter?", "options": [{"key": "A", "text": "Stay together for group protection"}, {"key": "B", "text": "Building nests"}, {"key": "C", "text": "Migrate to a new place"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q057.mp3", "transcript": "Welcome everyone today we'll explore some interesting bird behaviors throughout the year in Spring birds are busy building nests and finding mates preparing for the arrival of their young during summer they're focused on feeding their chicks and teaching them how to fly as Autumn approaches many birds begin to migrate Gathering food and energy for their long trip South in winter birds tend to stay together in groups for protection from predators each season brings out different survival strategies in these amazing creatures", "translation": "Chào mừng mọi người hôm nay chúng ta sẽ khám phá một số hành vi thú vị của loài chim trong suốt mùa xuân. Những chú chim đang bận rộn xây tổ và tìm bạn tình để chuẩn bị cho sự xuất hiện của con non trong mùa hè. Chúng tập trung vào việc cho chim con ăn và dạy chúng cách bay khi mùa thu đến gần. Nhiều loài chim bắt đầu di cư Thu thập thức ăn và năng lượng cho chuyến đi dài về phía nam vào mùa đông, các loài chim có xu hướng ở cùng nhau để bảo vệ khỏi những kẻ săn mồi, mỗi mùa đưa ra các chiến lược sinh tồn khác nhau ở những sinh vật tuyệt vời này", "question_vi": "Một hướng dẫn viên du lịch đang nói về hành vi của các loài chim. Chim làm gì vào mùa đông?", "answer_guess": true, "extra": ["Feed their chicks", "Look for mates"], "audio": "data/Aptis_Listening_P1_De02/audio/q06.mp3"}, {"id": 7, "question": "A man and a woman are talking about driving. Why did the man learn to drive?", "options": [{"key": "A", "text": "He lost his driving license."}, {"key": "B", "text": "He has to drive to work."}, {"key": "C", "text": "He bought a new car."}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q058.mp3", "transcript": "Hey Sarah I've got some news I'm moving to a new place oh really that sounds exciting where's your new place it's actually pretty far from my workplace and the public transport there isn't great so I've been thinking I need to learn how to drive yeah that makes sense it's hard to rely on public transport if it's not reliable have you ever driven before not really I've always used buses and trains but now it looks like I don't have a choice I need to get a license you'll get the hang of it driving will definitely make your commute easier are you planning to take lessons soon yeah I'm going to sign up for a driving school next week hopefully I can get it done quickly", "translation": "Này Sarah Tôi có một số tin tức Tôi sắp chuyển đến một nơi mới ồ, điều đó thật thú vị. Nơi ở mới của bạn ở đâu, nó thực sự khá xa nơi làm việc của tôi và phương tiện giao thông công cộng ở đó không tốt nên tôi đang nghĩ mình cần học cách lái xe vâng, điều đó hợp lý nếu nó không đáng tin cậy thì thật khó để dựa vào phương tiện công cộng nếu nó không đáng tin cậy. Bạn đã từng lái xe trước đây chưa? Tôi luôn sử dụng xe buýt và xe lửa nhưng bây giờ có vẻ như tôi không có lựa chọn nào khác. Tôi cần phải có bằng lái, bạn sẽ quen với nó việc lái xe chắc chắn sẽ giúp việc đi lại của bạn dễ dàng hơn bạn có định đi học sớm không vâng tôi sẽ đăng ký một trường dạy lái xe vào tuần tới hy vọng tôi có thể hoàn thành việc đó nhanh chóng", "question_vi": "Một người đàn ông và một người phụ nữ đang nói chuyện về việc lái xe. Tại sao người đàn ông học lái xe?", "answer_guess": true, "extra": ["He wanted to travel more", "His friends asked him to"], "audio": "data/Aptis_Listening_P1_De02/audio/q07.mp3"}, {"id": 8, "question": "An expert is talking about lack of satisfaction at work. What did she advise for people who lack motivation at work?", "options": [{"key": "A", "text": "Raise the salary"}, {"key": "B", "text": "Seek a new job"}, {"key": "C", "text": "Request a transfer"}], "answer": "C", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q059.mp3", "transcript": "Many people feel unhappy at work and often they think a higher salary or less work will fix it but that's not always the solution sometimes the problem is the work environment a change of place can help improve how we feel at work however looking for a new job can be stressful and take time one option is to ask for a transfer to another Branch within the same company this can offer the same benefits as getting a new job without the challenges of starting over somewhere new", "translation": "Nhiều người cảm thấy không vui ở nơi làm việc và họ thường nghĩ rằng mức lương cao hơn hoặc công việc ít hơn sẽ giải quyết được vấn đề nhưng đó không phải lúc nào cũng là giải pháp. Đôi khi, vấn đề là môi trường làm việc, sự thay đổi địa điểm có thể giúp cải thiện cảm giác của chúng ta tại nơi làm việc. Tuy nhiên, việc tìm kiếm một công việc mới có thể căng thẳng và mất thời gian.", "question_vi": "Một chuyên gia đang nói về sự thiếu hài lòng trong công việc. Cô đã khuyên gì cho những người thiếu động lực trong công việc?", "answer_guess": true, "extra": ["Work fewer hours", "Take a long holiday"], "audio": "data/Aptis_Listening_P1_De02/audio/q08.mp3"}, {"id": 9, "question": "A man is calling his colleague about a meeting with clients. When will the meeting start?", "options": [{"key": "A", "text": "at 9.15"}, {"key": "B", "text": "at 10.15"}, {"key": "C", "text": "at 11.15"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q060.mp3", "transcript": "Hey just wanted to give you a quick heads up I won't be able to join the meeting with the clients at 10:15 like we planned I've got something that suddenly came up I know it's last minute but could you go ahead and handle the presentation on your own you're familiar with everything so I trust you've got this let me know how it goes afterwards thanks I really appreciate it", "translation": "Này, tôi chỉ muốn thông báo nhanh cho bạn. Tôi sẽ không thể tham gia cuộc họp với khách hàng lúc 10:15 như chúng ta đã lên kế hoạch. Tôi có vài việc đột nhiên nảy ra. Tôi biết đó là phút cuối nhưng bạn có thể tiếp tục và tự mình xử lý bài thuyết trình được không. Bạn đã quen thuộc với mọi thứ nên tôi tin rằng bạn đã hiểu được điều này, hãy cho tôi biết mọi việc diễn ra sau đó như thế nào, cảm ơn tôi thực sự đánh giá cao nó", "question_vi": "Một người đàn ông đang gọi điện cho đồng nghiệp của mình về cuộc họp với khách hàng. Khi nào cuộc họp sẽ bắt đầu?", "answer_guess": true, "extra": ["at 10.45", "at 9.45"], "audio": "data/Aptis_Listening_P1_De02/audio/q09.mp3"}, {"id": 10, "question": "A man is calling his friend, Maria. When will he see her?", "options": [{"key": "A", "text": "at 9 am on Sunday"}, {"key": "B", "text": "at 10 am on Saturday"}, {"key": "C", "text": "at 8 am on Sunday"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q061.mp3", "transcript": "Hey Maria it's me I wanted to give you a quick call to let you know that I'll be visiting your town this weekend I've got a few things planned going to check out the local market and maybe explore some of the nearby parks but the best part I'll finally get to see you I'll be at your place at 9:00 a.m. on Sunday so we can catch up can't wait to hang out", "translation": "Này Maria, tôi là tôi. Tôi muốn gọi nhanh cho bạn để thông báo rằng tôi sẽ đến thăm thị trấn của bạn vào cuối tuần này. Tôi đã lên kế hoạch cho một số việc là đi dạo chợ địa phương và có thể khám phá một số công viên gần đó nhưng điều tuyệt vời nhất là cuối cùng tôi cũng được gặp bạn. Tôi sẽ có mặt tại nhà bạn lúc 9 giờ sáng Chủ nhật để chúng ta có thể trò chuyện. Nóng lòng được đi chơi", "question_vi": "Một người đàn ông đang gọi cho bạn mình, Maria. Khi nào anh ấy sẽ gặp cô ấy?", "answer_guess": true, "extra": ["at 9 am on Saturday", "at 10 am on Sunday"], "audio": "data/Aptis_Listening_P1_De02/audio/q10.mp3"}, {"id": 11, "question": "Adam is calling his friend. When will he need the computer?", "options": [{"key": "A", "text": "Tuesday"}, {"key": "B", "text": "Friday"}, {"key": "C", "text": "Saturday"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q062.mp3", "transcript": "Hey James it's Adam I just wanted to give you a quick call I know you need a computer for your project so I'm happy to let you borrow mine on Tuesday just make sure to take good care of it but I need it back by Friday because I have a group presentation on Saturday I really appreciate it and I'm sure you will get a lot done with it let me know if that works for you see you soon", "translation": "Này James, tôi là Adam, tôi chỉ muốn gọi nhanh cho bạn. Tôi biết bạn cần một chiếc máy tính cho dự án của mình nên tôi rất vui được cho bạn mượn máy tính của tôi vào thứ Ba, chỉ cần đảm bảo giữ gìn nó cẩn thận nhưng tôi cần trả lại trước thứ Sáu vì tôi có một buổi thuyết trình nhóm vào thứ Bảy. Tôi thực sự đánh giá cao nó và tôi chắc chắn rằng bạn sẽ làm được nhiều việc với nó. Hãy cho tôi biết nếu điều đó có ích cho bạn. Hẹn gặp lại bạn sớm", "question_vi": "Adam đang gọi cho bạn mình. Khi nào anh ấy sẽ cần máy tính?", "answer_guess": true, "extra": ["Monday", "Thursday"], "audio": "data/Aptis_Listening_P1_De02/audio/q11.mp3"}, {"id": 12, "question": "Listen to a weather forecast. Where will the weather be best?", "options": [{"key": "A", "text": "In the south"}, {"key": "B", "text": "In the west"}, {"key": "C", "text": "In the east"}], "answer": "C", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q063.mp3", "transcript": "Good evening everyone here's your weather update for today unfortunately the weather down south isn't looking too great strong winds and heavy rain are expected throughout the day so it might be best to avoid any outdoor plans in that region on a brighter note the West will have decent weather with clear skies and Mild temperatures making it a nice option if you're looking for some fresh air however the best weather can be found in the east sunny skies and perfect temperatures for any outdoor activities if you're planning to travel I highly recommend heading east for the best conditions safe travels and make sure to check local forecasts for any changes", "translation": "Chào buổi tối mọi người, đây là thông tin cập nhật về thời tiết hôm nay của bạn, tiếc là thời tiết ở phía nam không quá lớn, gió mạnh và dự kiến sẽ có mưa lớn suốt cả ngày vì vậy tốt nhất bạn nên tránh mọi kế hoạch ngoài trời ở khu vực đó với điều kiện sáng sủa hơn. Miền Tây sẽ có thời tiết tốt với bầu trời trong xanh và nhiệt độ ôn hòa nên đây là một lựa chọn tuyệt vời nếu bạn đang tìm kiếm không khí trong lành tuy nhiên thời tiết tốt nhất có thể được tìm thấy ở bầu trời đầy nắng phía đông và nhiệt độ hoàn hảo cho bất kỳ hoạt động ngoài trời nào nếu bạn định đi du lịch. Tôi khuyên bạn nên đi về phía đông để có điều kiện tốt nhất cho chuyến đi an toàn và hãy nhớ kiểm tra dự báo địa phương về mọi thay đổi", "question_vi": "Nghe dự báo thời tiết. Thời tiết ở đâu sẽ tốt nhất?", "answer_guess": true, "extra": ["In the north", "In the centre"], "audio": "data/Aptis_Listening_P1_De02/audio/q12.mp3"}, {"id": 13, "question": "A man is talking about how he goes to work. Why does he prefer traveling by train?", "options": [{"key": "A", "text": "It's cheaper than biking"}, {"key": "B", "text": "It's practical"}, {"key": "C", "text": "It's faster than flying"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q064.mp3", "transcript": "I've been thinking about how to get to work everyday at first I considered driving but the traffic is always really bad in the morning then I thought about riding my bike but it's too far and I'd be tired before I even start my day the bus is another option but it's often late after thinking about all the choices I decided to travel by train it's practical because it's on time and I can relax during the trip plus the station is close to my office", "translation": "Tôi đã nghĩ đến việc làm thế nào để đi làm hàng ngày lúc đầu. Tôi đã cân nhắc việc lái xe nhưng giao thông luôn rất tệ vào buổi sáng, sau đó tôi nghĩ đến việc đi xe đạp nhưng nó quá xa và tôi sẽ mệt trước khi bắt đầu ngày mới. Xe buýt là một lựa chọn khác nhưng thường muộn sau khi suy nghĩ về tất cả các lựa chọn. Tôi quyết định đi bằng tàu hỏa, nó rất thiết thực vì nó đúng giờ và tôi có thể thư giãn trong suốt chuyến đi cộng với nhà ga gần văn phòng của tôi", "question_vi": "Một người đàn ông đang nói về cách anh ta đi làm. Tại sao anh ấy thích đi du lịch bằng tàu hỏa?", "answer_guess": true, "extra": ["It's cheaper than the bus", "It has free wifi"], "audio": "data/Aptis_Listening_P1_De02/audio/q13.mp3"}, {"id": 14, "question": "A woman is talking about her family's holidays. What did the family do last year?", "options": [{"key": "A", "text": "Traveled abroad"}, {"key": "B", "text": "Camping"}, {"key": "C", "text": "Went to the beach"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q065.mp3", "transcript": "This year my family and I are going to the beach for our holiday I'm really excited because I love swimming and relaxing by the Sea last year we went camping on the mountain which was fun but this time we wanted to do something different we're staying in a small house near the beach and I can't wait to watch the sunset every evening my kids are excited too they want to build sand castles and play in the water I think it's going to be a great holiday", "translation": "Năm nay tôi và gia đình sẽ đi biển vào kỳ nghỉ của mình. Tôi thực sự rất hào hứng vì tôi thích bơi lội và thư giãn bên bờ biển. Năm ngoái chúng tôi đã đi cắm trại trên núi, điều đó thật thú vị nhưng lần này chúng tôi muốn làm điều gì đó khác biệt. Chúng tôi đang ở trong một ngôi nhà nhỏ gần bãi biển và tôi rất nóng lòng được ngắm hoàng hôn mỗi tối, các con tôi cũng rất hào hứng. Chúng muốn xây lâu đài cát và chơi dưới nước. Tôi nghĩ đây sẽ là một kỳ nghỉ tuyệt vời", "question_vi": "Một người phụ nữ đang nói về những ngày nghỉ của gia đình cô ấy. Năm ngoái gia đình đã làm gì?", "answer_guess": true, "extra": ["Visited relatives", "Went skiing"], "audio": "data/Aptis_Listening_P1_De02/audio/q14.mp3"}, {"id": 15, "question": "A mom is talking to her son. What does he like to study?", "options": [{"key": "A", "text": "Art"}, {"key": "B", "text": "Science"}, {"key": "C", "text": "History"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q066.mp3", "transcript": "Hey sweetheart I'm so proud of you your art project looks amazing you're really talented I love how you used all those bright colors you always do such a great job with your drawings but remember you also need to spend some time on your other subjects too like math and science I know you can do well in those if you try hard just like you do with art let's work on it together okay", "translation": "Này em yêu, anh rất tự hào về em, dự án nghệ thuật của em trông thật tuyệt vời em thật tài năng Tôi thích cách em sử dụng tất cả những màu sắc tươi sáng đó em luôn làm rất tốt những bức vẽ của mình nhưng hãy nhớ rằng em cũng cần dành chút thời gian cho các môn học khác như toán và khoa học. Tôi biết em có thể học tốt những môn đó nếu em cố gắng chăm chỉ giống như nghệ thuật, chúng ta hãy cùng nhau nỗ lực nhé.", "question_vi": "Một người mẹ đang nói chuyện với con trai mình. Anh ấy thích học gì?", "answer_guess": true, "extra": ["Math", "Music"], "audio": "data/Aptis_Listening_P1_De02/audio/q15.mp3"}, {"id": 16, "question": "Anne calls her daughter Sally. What does she need?", "options": [{"key": "A", "text": "Eggs"}, {"key": "B", "text": "Bread"}, {"key": "C", "text": "Milk"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q067.mp3", "transcript": "I just wanted to remind you about dinner tonight we're having your favorite spaghetti don't forget to pick up your brother from school at 4:00 oh and can you stop by the store on your way home we're out of eggs and I need some to finish baking the cake thanks sweetie", "translation": "Tôi chỉ muốn nhắc bạn về bữa tối tối nay, chúng tôi có món mì spaghetti yêu thích của bạn, đừng quên đón anh trai bạn từ trường vào lúc 4 giờ ồ và bạn có thể ghé qua cửa hàng trên đường về nhà không, chúng tôi hết trứng rồi và tôi cần một ít để nướng xong chiếc bánh, cảm ơn em yêu", "question_vi": "Anne gọi con gái mình là Sally. Cô ấy cần gì?", "answer_guess": true, "extra": ["Butter", "Sugar"], "audio": "data/Aptis_Listening_P1_De02/audio/q16.mp3"}, {"id": 17, "question": "A teacher and a student are talking about transportation. How does the teacher go to school?", "options": [{"key": "A", "text": "He drives"}, {"key": "B", "text": "He takes the bus"}, {"key": "C", "text": "He walks"}], "answer": "C", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q068.mp3", "transcript": "Good morning Sarah you are early today how do you get to school everyday hi Mr Smith I usually take the bus it's not far from my house but sometimes I have to wait a long time for it I understand I walked to school everyday but the bus is faster for me especially when I have to get here early", "translation": "Chào buổi sáng Sarah hôm nay bạn đến sớm bằng cách nào bạn đến trường hàng ngày xin chào ông Smith Tôi thường đi xe buýt cách nhà tôi không xa nhưng đôi khi tôi phải đợi rất lâu Tôi hiểu rằng tôi đi bộ đến trường hàng ngày nhưng xe buýt nhanh hơn đối với tôi đặc biệt là khi tôi phải đến đây sớm", "question_vi": "Một giáo viên và một học sinh đang nói về giao thông. Giáo viên đi học bằng cách nào?", "answer_guess": true, "extra": ["He cycles", "He takes the train"], "audio": "data/Aptis_Listening_P1_De02/audio/q17.mp3"}, {"id": 18, "question": "A woman is talking about her weekends. What did she do last week?", "options": [{"key": "A", "text": "Went hiking"}, {"key": "B", "text": "Stayed at home"}, {"key": "C", "text": "Attended a party"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q069.mp3", "transcript": "My weekends are not always the same this week has been busy but I always look forward to my free time last weekend I stayed at home and enjoyed some Quiet Moments with a good book I also watched a few movies and cooked a nice dinner for myself this weekend I plan to go out with friends we might visit a new cafe or go for a walk in the park I love spending time with my friends and relaxing after a busy week", "translation": "Những ngày cuối tuần của tôi không phải lúc nào cũng giống nhau trong tuần này bận rộn nhưng tôi luôn mong có thời gian rảnh cuối tuần trước Tôi ở nhà và tận hưởng những khoảnh khắc yên tĩnh với một cuốn sách hay Tôi cũng xem một vài bộ phim và nấu một bữa tối ngon cho mình vào cuối tuần này Tôi dự định đi chơi với bạn bè, chúng tôi có thể ghé một quán cà phê mới hoặc đi dạo trong công viên Tôi thích dành thời gian với bạn bè và thư giãn sau một tuần bận rộn", "question_vi": "Một người phụ nữ đang nói về những ngày cuối tuần của cô ấy. Tuần trước cô ấy đã làm gì?", "answer_guess": true, "extra": ["Visited a cafe", "Went to the cinema"], "audio": "data/Aptis_Listening_P1_De02/audio/q18.mp3"}, {"id": 19, "question": "Listen to a conversation between the teacher and a parent. What will the father do?", "options": [{"key": "A", "text": "Enroll him in summer school"}, {"key": "B", "text": "Arrange private classes for his son"}, {"key": "C", "text": "Talk to the principal"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q070.mp3", "transcript": "Hello Mr Johnson thank you for coming in today I wanted to talk about your son Jake yes I've noticed he's been struggling a bit lately yes his performance is not so good in math and reading what can we do to help him I know a private tutor who works well with children she can provide extra help and support that sounds like a good idea can you give me her contact information of course I will write it down for you I think Jake will really benefit from it", "translation": "Xin chào ông Johnson, cảm ơn ông đã đến hôm nay Tôi muốn nói về con trai của ông, Jake vâng, tôi nhận thấy gần đây cháu đang gặp khó khăn một chút, vâng, thành tích của cháu không tốt lắm trong môn toán và đọc, chúng ta có thể làm gì để giúp cháu. Tôi biết một gia sư riêng làm việc tốt với trẻ em, cô ấy có thể giúp đỡ và hỗ trợ thêm, nghe có vẻ là một ý tưởng hay. Bạn có thể cho tôi thông tin liên hệ của cô ấy được không, tất nhiên tôi sẽ viết nó ra cho bạn. Tôi nghĩ Jake sẽ thực sự được hưởng lợi từ nó.", "question_vi": "Nghe đoạn hội thoại giữa giáo viên và phụ huynh. Người cha sẽ làm gì?", "answer_guess": true, "extra": ["Help him with homework himself", "Buy him more books"], "audio": "data/Aptis_Listening_P1_De02/audio/q19.mp3"}, {"id": 20, "question": "An artist is talking about her jobs. What is the difference in her job?", "options": [{"key": "A", "text": "She works from 9 to 5"}, {"key": "B", "text": "She doesn't work on weekends"}, {"key": "C", "text": "She works irregular hours"}], "answer": "C", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q071.mp3", "transcript": "Hello my name is Sarah and I'm an artist I paint pictures of nature like trees rivers and animals I love using bright colors to make my art happy and full of life my job is very fun but I work irregular hours sometimes late at night or on weekends when I have inspiration I paint for many hours without a break I sell my paintings and Galleries and online and it makes me really happy when people like my work creating art is the best job for me", "translation": "Xin chào, tên tôi là Sarah và tôi là một họa sĩ. Tôi vẽ những bức tranh về thiên nhiên như cây cối, dòng sông và động vật. Tôi thích sử dụng màu sắc tươi sáng để làm cho nghệ thuật của mình vui vẻ và tràn đầy sức sống. Công việc của tôi rất thú vị nhưng tôi làm việc nhiều giờ, đôi khi vào đêm khuya hoặc vào cuối tuần khi có cảm hứng. Tôi vẽ nhiều giờ không nghỉ. Tôi bán tranh và Phòng trưng bày của mình cũng như trực tuyến và điều đó khiến tôi thực sự hạnh phúc khi mọi người thích công việc sáng tạo nghệ thuật của tôi là công việc tốt nhất đối với tôi.", "question_vi": "Một nghệ sĩ đang nói về công việc của mình. Sự khác biệt trong công việc của cô ấy là gì?", "answer_guess": true, "extra": ["She works only at night", "She works only on weekends"], "audio": "data/Aptis_Listening_P1_De02/audio/q20.mp3"}, {"id": 21, "question": "Listen to an announcement. Which platform to wait for the train?", "options": [{"key": "A", "text": "Platform 2"}, {"key": "B", "text": "Platform 5"}, {"key": "C", "text": "Platform 8"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q072.mp3", "transcript": "Attention all passengers the 1030 train to Greenfield is now arriving at platform 2 please make sure you have your ticket ready before boarding this train will stop at River station and Oakwood before reaching its final destination be careful when stepping onto the train and mine the gap for your safety please keep your belongings close and follow all instructions from the staff thank you for traveling with us today", "translation": "Xin lưu ý tất cả các hành khách, chuyến tàu 1030 đến Greenfield hiện đang đến sân ga số 2, vui lòng đảm bảo rằng bạn đã chuẩn bị sẵn vé trước khi lên tàu. Chuyến tàu này sẽ dừng ở ga River và Oakwood trước khi đến điểm đến cuối cùng, hãy cẩn thận khi bước lên tàu và tránh khoảng trống để đảm bảo an toàn cho bạn. Vui lòng giữ đồ đạc của bạn cẩn thận và làm theo mọi hướng dẫn từ nhân viên, cảm ơn bạn đã đi cùng chúng tôi hôm nay", "question_vi": "Nghe một thông báo. Sân ga nào để chờ tàu?", "answer_guess": true, "extra": ["Platform 3", "Platform 10"], "audio": "data/Aptis_Listening_P1_De02/audio/q21.mp3"}, {"id": 22, "question": "A man is talking about his jobs. What does the man want to do next?", "options": [{"key": "A", "text": "Become a writer"}, {"key": "B", "text": "Become a chef again"}, {"key": "C", "text": "Start teaching history again"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q073.mp3", "transcript": "I used to be a chef and I loved cooking different dishes for people it was exciting to create new recipes but it was also very hard work after that I became a history teacher where I enjoyed sharing stories about the past with my student teaching was rewarding but I wanted to try something new now I want to become a writer I have many ideas for stories in my mind and I can't wait to put them on paper", "translation": "Tôi từng là một đầu bếp và tôi thích nấu những món ăn khác nhau cho mọi người, thật thú vị khi tạo ra những công thức nấu ăn mới nhưng cũng rất vất vả sau đó tôi trở thành một giáo viên lịch sử, nơi tôi thích chia sẻ những câu chuyện về quá khứ với việc giảng dạy học sinh của mình thật bổ ích nhưng tôi muốn thử một điều gì đó mới mẻ. Bây giờ tôi muốn trở thành một nhà văn. Tôi có rất nhiều ý tưởng cho những câu chuyện trong đầu và tôi rất nóng lòng muốn viết chúng ra giấy", "question_vi": "Một người đàn ông đang nói về công việc của mình. Người đàn ông muốn làm gì tiếp theo?", "answer_guess": true, "extra": ["Become a doctor", "Open a restaurant"], "audio": "data/Aptis_Listening_P1_De02/audio/q22.mp3"}, {"id": 23, "question": "Listen to a tour guide talk about why a tour was canceled. What was the reason?", "options": [{"key": "A", "text": "Not enough people"}, {"key": "B", "text": "Bad weather"}, {"key": "C", "text": "Transportation problems"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q074.mp3", "transcript": "Hello everyone I hope you're all having a good day I'm your tour guide and I was really looking forward to showing you around the city today however there is a small issue the weather is perfect and transportation is not a problem everything is ready for our trip certainly these are not the problems unfortunately we don't have enough people for the tour today because of this we have to cancel the tour I'm really sorry for the inconvenience and I hope we can see you next time", "translation": "Xin chào mọi người Tôi hy vọng tất cả các bạn có một ngày tốt lành Tôi là hướng dẫn viên du lịch của bạn và tôi thực sự mong được dẫn bạn đi tham quan thành phố hôm nay tuy nhiên có một vấn đề nhỏ là thời tiết rất hoàn hảo và giao thông không thành vấn đề Mọi thứ đã sẵn sàng cho chuyến đi của chúng tôi chắc chắn đây không phải là vấn đề tiếc là chúng tôi không có đủ người cho chuyến tham quan hôm nay vì điều này chúng tôi phải hủy chuyến tham quan Tôi thực sự xin lỗi vì sự bất tiện này và tôi hy vọng chúng ta có thể gặp bạn lần sau", "question_vi": "Nghe hướng dẫn viên du lịch nói về lý do chuyến tham quan bị hủy. Lý do là gì?", "answer_guess": true, "extra": ["The guide was ill", "The museum was closed"], "audio": "data/Aptis_Listening_P1_De02/audio/q23.mp3"}, {"id": 24, "question": "A woman is talking about shopping places. Where does she go shopping?", "options": [{"key": "A", "text": "At the downtown market"}, {"key": "B", "text": "At a new shopping center"}, {"key": "C", "text": "At the mall"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q075.mp3", "transcript": "I love shopping and there are so many places to choose from in our city the downtown Market is great for fresh fruit and vegetables and there are lots of small shops there too if I need clothes I usually go to the mall but it can get very crowded on weekends there's also a little boutique near my house with some unique items but it's a bit expensive this time I'm excited to check out the new shopping center that just opened I've heard it has everything I need in one place", "translation": "Tôi thích mua sắm và có rất nhiều nơi để lựa chọn trong thành phố của chúng tôi, trung tâm thành phố Chợ rất thích hợp để mua trái cây và rau quả tươi và ở đó cũng có rất nhiều cửa hàng nhỏ nếu tôi cần quần áo. Tôi thường đến trung tâm mua sắm nhưng có thể rất đông vào cuối tuần cũng có một cửa hàng nhỏ gần nhà tôi với một số mặt hàng độc đáo nhưng lần này hơi đắt. Tôi rất hào hứng muốn xem trung tâm mua sắm mới vừa khai trương Tôi nghe nói nó có mọi thứ tôi cần ở một nơi", "question_vi": "Một người phụ nữ đang nói về những nơi mua sắm. Cô ấy đi mua sắm ở đâu?", "answer_guess": true, "extra": ["At a small boutique", "Online"], "audio": "data/Aptis_Listening_P1_De02/audio/q24.mp3"}, {"id": 25, "question": "Listen to the instructions of a university. Where is the main office?", "options": [{"key": "A", "text": "On the third floor"}, {"key": "B", "text": "On the first floor"}, {"key": "C", "text": "In the basement"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q076.mp3", "transcript": "Welcome to our University when you enter the campus you'll see the library on your left and the cafeteria on your right if you need help with anything the main office is on the first floor of the center campus Building there you can ask about classes schedules or anything else behind the main building you'll find the gym and sports area for quiet study there are some nice spots in the garden near the science building make sure to explore and enjoy your time here", "translation": "Chào mừng bạn đến với trường Đại học của chúng tôi khi bạn vào khuôn viên trường, bạn sẽ thấy thư viện ở bên trái và quán cà phê ở bên phải nếu bạn cần trợ giúp về bất cứ điều gì văn phòng chính nằm ở tầng một của khuôn viên trung tâm Tòa nhà ở đó bạn có thể hỏi về lịch học hoặc bất cứ điều gì khác phía sau tòa nhà chính bạn sẽ tìm thấy phòng tập thể dục và khu thể thao để học tập yên tĩnh có một số địa điểm đẹp trong khu vườn gần tòa nhà khoa học, hãy đảm bảo bạn khám phá và tận hưởng thời gian ở đây", "question_vi": "Nghe hướng dẫn của một trường đại học. Văn phòng chính ở đâu?", "answer_guess": true, "extra": ["On the second floor", "On the top floor"], "audio": "data/Aptis_Listening_P1_De02/audio/q25.mp3"}, {"id": 26, "question": "A finance expert is giving advice to young people. What shouldn't they do?", "options": [{"key": "A", "text": "Spend too much on clothes."}, {"key": "B", "text": "Ask for more money."}, {"key": "C", "text": "Save for emergencies."}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q077.mp3", "transcript": "Managing money is very important for everyone I always make sure to plan my spending carefully like saving some for emergencies and not buying things I don't need it's easy to lose control if you don't keep track of your budget young people especially need to be careful about borrowing money many ask for loans from the bank but that creates debt it's better to avoid borrowing too much and focus on saving instead", "translation": "Quản lý tiền bạc rất quan trọng đối với mọi người Tôi luôn đảm bảo lập kế hoạch chi tiêu cẩn thận như tiết kiệm một ít cho những trường hợp khẩn cấp và không mua những thứ Tôi không cần rất dễ mất kiểm soát nếu bạn không theo dõi ngân sách của mình. Những người trẻ đặc biệt cần phải cẩn thận khi vay tiền, nhiều người xin vay ngân hàng nhưng điều đó tạo ra nợ tốt hơn hết là tránh vay quá nhiều và thay vào đó hãy tập trung vào tiết kiệm", "question_vi": "Một chuyên gia tài chính đang đưa ra lời khuyên cho giới trẻ. Họ không nên làm gì?", "answer_guess": true, "extra": ["Plan their spending", "Keep track of their budget"], "audio": "data/Aptis_Listening_P1_De02/audio/q26.mp3"}, {"id": 27, "question": "Lucy is calling her friend. What is her sister like?", "options": [{"key": "A", "text": "She is young"}, {"key": "B", "text": "They have similar characters"}, {"key": "C", "text": "She will be wearing red coat"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q078.mp3", "transcript": "Hi Emma it's Lucy I hope you're doing well I need a small favor from you today could you pick up my sister after school she'll be standing at the school gate at 3:00 p.m. she looks just like me so you'll recognize her easily I have a meeting and I won't make it in time thank you so much let me know if that's okay with you", "translation": "Xin chào Emma, ​​tôi là Lucy Tôi hy vọng bạn vẫn ổn Tôi cần một sự giúp đỡ nhỏ từ bạn hôm nay bạn có thể đón em gái tôi sau giờ học không, cô ấy sẽ đứng ở cổng trường lúc 3 giờ chiều. cô ấy trông giống tôi nên bạn sẽ dễ dàng nhận ra cô ấy. Tôi có một cuộc họp và tôi sẽ không đến kịp, cảm ơn bạn rất nhiều, hãy cho tôi biết liệu bạn có đồng ý không", "question_vi": "Lucy đang gọi cho bạn cô ấy. Chị gái cô ấy là người như thế nào?", "answer_guess": true, "extra": ["She has short hair", "She is very tall"], "audio": "data/Aptis_Listening_P1_De02/audio/q27.mp3"}, {"id": 28, "question": "Tom is calling his friend. What time will they meet?", "options": [{"key": "A", "text": "6 PM"}, {"key": "B", "text": "5 PM"}, {"key": "C", "text": "7 PM"}], "answer": "C", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q079.mp3", "transcript": "Hey Mike it's Tom how are you I was thinking why don't we meet up tonight I'm free and it would be fun to hang out let's meet at the park at 7:00 p.m. does that work for you we can grab some snacks and maybe play basketball or just talk let me know if you're in and if anyone else wants to join we can invite them to see you later", "translation": "Này Mike, đây là Tom, bạn khỏe không. Tôi đang nghĩ tại sao chúng ta không gặp nhau tối nay. Tôi rảnh và sẽ rất vui nếu được đi chơi. Hãy gặp nhau ở công viên lúc 7 giờ tối nhé. điều đó có phù hợp với bạn không? Chúng ta có thể mua chút đồ ăn nhẹ và có thể chơi bóng rổ hoặc chỉ nói chuyện cho tôi biết nếu bạn tham gia và nếu có ai khác muốn tham gia, chúng ta có thể mời họ gặp bạn sau", "question_vi": "Tom đang gọi cho bạn anh ấy. Họ sẽ gặp nhau lúc mấy giờ?", "answer_guess": true, "extra": ["8 PM", "6:30 PM"], "audio": "data/Aptis_Listening_P1_De02/audio/q28.mp3"}, {"id": 29, "question": "A boy is talking about his cat. What does he feed the cat?", "options": [{"key": "A", "text": "Mice"}, {"key": "B", "text": "Insects"}, {"key": "C", "text": "Fish"}], "answer": "C", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q080.mp3", "transcript": "Hi I'm Alex and I want to tell you about my cat whiskers he's really friendly and loves to play whiskers is a bit picky about food though he doesn't like eating mice or insects which is funny for a cat but he absolutely loves fish every time I give him some he gets so excited he also enjoys sleeping by the window and watching the birds outside is the best pet ever", "translation": "Xin chào, tôi là Alex và tôi muốn kể cho bạn nghe về bộ râu mèo của tôi, anh ấy thực sự thân thiện và thích chơi râu, hơi kén chọn thức ăn mặc dù anh ấy không thích ăn chuột hoặc côn trùng, điều này thật buồn cười đối với mèo nhưng anh ấy cực kỳ thích cá mỗi khi tôi cho anh ấy một ít, anh ấy rất phấn khích, anh ấy cũng thích ngủ bên cửa sổ và ngắm nhìn những chú chim bên ngoài là thú cưng tuyệt vời nhất từ ​​trước đến nay", "question_vi": "Một cậu bé đang nói về con mèo của mình. Anh ấy cho mèo ăn gì?", "answer_guess": true, "extra": ["Birds", "Cheese"], "audio": "data/Aptis_Listening_P1_De02/audio/q29.mp3"}, {"id": 30, "question": "A girl is talking about a show she will attend. What will it end with?", "options": [{"key": "A", "text": "A dance performance"}, {"key": "B", "text": "A big celebration"}, {"key": "C", "text": "A surprise performance"}], "answer": "C", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q081.mp3", "transcript": "Hi I'm Emma and I'm super excited about a show I'm going to this weekend it's happening on Saturday at 7:00 p.m. at the city theater there will be different performances like dancing and singing I've heard the show is really fun and I can't wait to see it but the best part is that it will end with a surprise performance I'm really curious to find out what it is", "translation": "Xin chào, tôi là Emma và tôi cực kỳ hào hứng với buổi biểu diễn mà tôi sẽ tham gia vào cuối tuần này, nó sẽ diễn ra vào lúc 7 giờ tối Thứ Bảy. tại nhà hát thành phố sẽ có những màn biểu diễn khác nhau như khiêu vũ và ca hát. Tôi nghe nói buổi biểu diễn rất thú vị và tôi rất nóng lòng muốn xem nhưng điều tuyệt vời nhất là nó sẽ kết thúc bằng một màn trình diễn bất ngờ. Tôi thực sự tò mò muốn biết nó là gì", "question_vi": "Một cô gái đang nói về một chương trình mà cô ấy sẽ tham dự. Nó sẽ kết thúc bằng gì?", "answer_guess": true, "extra": ["A singing contest", "A fireworks display"], "audio": "data/Aptis_Listening_P1_De02/audio/q30.mp3"}, {"id": 31, "question": "Listen to a student talking about his study. What course is the student going to take this year?", "options": [{"key": "A", "text": "Math"}, {"key": "B", "text": "Computer"}, {"key": "C", "text": "Science"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q082.mp3", "transcript": "Hi I'm Ben and I want to share a bit about my studies last term I took English Math and Science they were all interesting but math was a bit tough for me I worked hard though and got good results in the end this year I'm really excited because I'm going to take a computer course I've always wanted to learn more about technology so I'm looking forward to it", "translation": "Xin chào, tôi là Ben và tôi muốn chia sẻ một chút về việc học của mình trong học kỳ trước. Tôi đã học môn Toán và Khoa học bằng tiếng Anh. Tất cả đều thú vị nhưng môn toán hơi khó đối với tôi. Tuy nhiên, tôi đã học tập chăm chỉ và đạt kết quả tốt vào cuối năm nay. Tôi thực sự rất hào hứng vì tôi sắp tham gia một khóa học máy tính. Tôi luôn muốn tìm hiểu thêm về công nghệ nên tôi rất mong chờ nó.", "question_vi": "Lắng nghe một sinh viên nói về việc học của mình. Học sinh sẽ học khóa học nào trong năm nay?", "answer_guess": true, "extra": ["English", "Art"], "audio": "data/Aptis_Listening_P1_De02/audio/q31.mp3"}, {"id": 32, "question": "Listen to a saleswoman talking about a property. Which room is the largest?", "options": [{"key": "A", "text": "Bedroom"}, {"key": "B", "text": "Kitchen"}, {"key": "C", "text": "Bathroom"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q083.mp3", "transcript": "It has two spacious bedrooms both with big windows that led in lots of natural light the bathroom is modern with a large shower and plenty of storage space the living room is cozy perfect for relaxing after a long day but the kitchen is the star of the house it's the largest room with lots of counter space for cooking and it's great for hosting dinners you'll love it here", "translation": "Nó có hai phòng ngủ rộng rãi, cả hai đều có cửa sổ lớn đón nhiều ánh sáng tự nhiên, phòng tắm hiện đại với vòi sen lớn và nhiều không gian đựng đồ, phòng khách ấm cúng, hoàn hảo để thư giãn sau một ngày dài nhưng nhà bếp là ngôi sao của ngôi nhà. Đây là phòng lớn nhất có nhiều không gian để nấu nướng và thật tuyệt vời để tổ chức bữa tối, bạn sẽ thích ở đây", "question_vi": "Hãy nghe người bán hàng nói về một bất động sản. Phòng nào lớn nhất?", "answer_guess": true, "extra": ["Living room", "Dining room"], "audio": "data/Aptis_Listening_P1_De02/audio/q32.mp3"}, {"id": 33, "question": "Listen to a radio man talking about a new popular song. Which is the most attractive part of the song?", "options": [{"key": "A", "text": "The words"}, {"key": "B", "text": "The instruments"}, {"key": "C", "text": "The cover art"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q084.mp3", "transcript": "Good evening listeners today I want to talk about a new song that's quickly becoming popular you're my everything the tune is really catchy and it makes you want to dance right away the instruments used are simple but create a great rhythm however the most attractive part of all is the words the lyrics tell a beautiful story that everyone can relate to it's no wonder so many people are loving this song If you haven't heard it yet make sure to give it a listen soon", "translation": "Chào buổi tối các thính giả hôm nay Tôi muốn nói về một bài hát mới đang nhanh chóng trở nên phổ biến, bạn là tất cả của tôi, giai điệu thực sự hấp dẫn và nó khiến bạn muốn nhảy ngay lập tức. Nhạc cụ được sử dụng rất đơn giản nhưng tạo ra nhịp điệu tuyệt vời, tuy nhiên phần hấp dẫn nhất là lời bài hát kể một câu chuyện hay mà mọi người đều có thể liên tưởng đến. không có gì ngạc nhiên khi có rất nhiều người yêu thích bài hát này Nếu bạn chưa nghe thì hãy nhớ nghe thử sớm nhé", "question_vi": "Nghe người phát thanh nói về một bài hát nổi tiếng mới. Phần hấp dẫn nhất của bài hát là gì?", "answer_guess": true, "extra": ["The singer's voice", "The music video"], "audio": "data/Aptis_Listening_P1_De02/audio/q33.mp3"}, {"id": 34, "question": "A student is talking about housing. Where does he live now?", "options": [{"key": "A", "text": "In a small village"}, {"key": "B", "text": "In an apartment"}, {"key": "C", "text": "In a townhouse"}], "answer": "C", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q085.mp3", "transcript": "Hi I'm Jack and I want to talk about where I live right now I'm staying in a town hall near my University it's a nice place and I've met a lot of other students here before this I used to live with my parents in a small village it was quiet but I needed to be closer to school soon I'll move to an apartment nearby with a few friends I think it'll be fun to share a place with them I'm excited about the change", "translation": "Xin chào, tôi là Jack và tôi muốn nói về nơi tôi đang sống. Tôi đang ở trong một tòa thị chính gần trường đại học của tôi, đó là một nơi tuyệt vời và tôi đã gặp rất nhiều sinh viên khác ở đây trước đây. Tôi từng sống với bố mẹ trong một ngôi làng nhỏ, rất yên tĩnh nhưng tôi cần phải đến gần trường học sớm hơn. Tôi sẽ chuyển đến một căn hộ gần đó với một vài người bạn. Tôi nghĩ sẽ rất vui khi ở chung một nơi với họ Tôi rất vui vì sự thay đổi này", "question_vi": "Một sinh viên đang nói về nhà ở. Bây giờ anh ấy sống ở đâu?", "answer_guess": true, "extra": ["In a dormitory", "With his parents"], "audio": "data/Aptis_Listening_P1_De02/audio/q34.mp3"}, {"id": 35, "question": "A man is talking to a shop assistant. What does he want to buy?", "options": [{"key": "A", "text": "A T-shirt"}, {"key": "B", "text": "A suit for the office"}, {"key": "C", "text": "A pair of shoes"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q086.mp3", "transcript": "Hey Sarah let's check out the store I need something for work sure John how about this t-shirt it looks nice it's cool but I don't really need a t-shirt right now I'm actually looking for something more formal oh okay what about this hat it would look great on you haha maybe but not today I really need a suit for the office look this one seems perfect that's a good choice it's smart and looks comfortable great I will buy the suit let's keep looking for other things we need", "translation": "Này Sarah, hãy ghé qua cửa hàng Tôi cần thứ gì đó để đi làm, chắc chắn là John. Thế còn chiếc áo phông này thì nó trông đẹp đấy, nó ngầu nhưng tôi không thực sự cần một chiếc áo phông lúc này. Thực ra tôi đang tìm thứ gì đó trang trọng hơn ồ được rồi, thế còn chiếc mũ này sẽ rất hợp với bạn haha ​​có lẽ nhưng không phải hôm nay tôi thực sự cần một bộ đồ công sở, nhìn bộ đồ này có vẻ hoàn hảo, đó là một lựa chọn tốt, nó thông minh và trông rất thoải mái, tuyệt vời Tôi sẽ mua bộ đồ này, chúng ta hãy tiếp tục tìm kiếm những thứ khác mà chúng ta cần", "question_vi": "Một người đàn ông đang nói chuyện với nhân viên bán hàng. Anh ấy muốn mua gì?", "answer_guess": true, "extra": ["A hat", "A tie"], "audio": "data/Aptis_Listening_P1_De02/audio/q35.mp3"}, {"id": 36, "question": "A woman is talking to a police officer. What did she lose?", "options": [{"key": "A", "text": "Wallet"}, {"key": "B", "text": "Phone"}, {"key": "C", "text": "Car"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q087.mp3", "transcript": "Excuse me officer I need help please of course what happened I was walking in the park and I think I lost my phone I thought it was in my bag but now I can't find it I see don't worry we'll help you can you remember where you last saw it thank you so much officer okay will check the area please stay here for a moment and we'll try to find it for you thank you so much officer", "translation": "Xin lỗi sĩ quan, tôi cần giúp đỡ, tất nhiên chuyện gì đã xảy ra Tôi đang đi dạo trong công viên và tôi nghĩ là tôi bị mất điện thoại. Tôi nghĩ nó ở trong túi của tôi nhưng giờ tôi không thể tìm thấy nó. Tôi hiểu rồi, đừng lo, chúng tôi sẽ giúp bạn. Bạn có thể nhớ lần cuối bạn nhìn thấy nó ở đâu không, cảm ơn bạn rất nhiều, được rồi, tôi sẽ kiểm tra khu vực này, vui lòng ở lại đây một lát và chúng tôi sẽ cố gắng tìm nó cho bạn, cảm ơn sĩ quan rất nhiều", "question_vi": "Một người phụ nữ đang nói chuyện với một sĩ quan cảnh sát. Cô ấy đã mất gì?", "answer_guess": true, "extra": ["Bag", "Keys"], "audio": "data/Aptis_Listening_P1_De02/audio/q36.mp3"}, {"id": 37, "question": "Lily is talking about her daily routine. What does she do in the evening?", "options": [{"key": "A", "text": "Goes for a walk."}, {"key": "B", "text": "Plays video games."}, {"key": "C", "text": "Cooks dinner."}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q088.mp3", "transcript": "Hi I'm Lily and I want to tell you about my daily routine I wake up early around 6:30 a.m. and have breakfast before going to work I work in a small office and my job keeps me busy until about 5:00 p.m. after dinner I usually go for a walk to relax but today I'm going to try something different I'll do some yoga at home it sounds fun and peaceful after that I'll probably watch a movie before going to bed it's a simple day but I like it", "translation": "Xin chào, tôi là Lily và tôi muốn kể cho bạn nghe về thói quen hàng ngày của tôi. Tôi thức dậy sớm vào khoảng 6:30 sáng và ăn sáng trước khi đi làm. Tôi làm việc trong một văn phòng nhỏ và công việc khiến tôi bận rộn cho đến khoảng 5 giờ chiều. sau bữa tối tôi thường đi dạo để thư giãn nhưng hôm nay tôi sẽ thử một điều gì đó khác biệt Tôi sẽ tập yoga ở nhà nghe có vẻ vui và yên bình sau đó có lẽ tôi sẽ xem phim trước khi đi ngủ đó là một ngày đơn giản nhưng tôi thích nó", "question_vi": "Lily đang nói về thói quen hàng ngày của cô ấy. Cô ấy làm gì vào buổi tối?", "answer_guess": true, "extra": ["Reads books", "Goes to the cinema"], "audio": "data/Aptis_Listening_P1_De02/audio/q37.mp3"}, {"id": 38, "question": "A man is talking about his daily routine. What does he do after work?", "options": [{"key": "A", "text": "Goes to the gym."}, {"key": "B", "text": "Plays football."}, {"key": "C", "text": "Reads books."}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q089.mp3", "transcript": "Everyday I wake up at 7:00 a.m. and have a quick breakfast before going to work I usually take the bus and it takes about 30 minutes to get to the office at work I spend most of my time on the computer answering emails and working on projects I have lunch at noon and get back to work until 5:00 p.m. after work I like to relax by playing football with my friends it's a great way to stay active and have fun", "translation": "Hàng ngày tôi thức dậy lúc 7 giờ sáng và ăn sáng nhanh trước khi đi làm. Tôi thường đi xe buýt và mất khoảng 30 phút để đến văn phòng. Tôi dành phần lớn thời gian ngồi trên máy tính để trả lời email và làm việc trên các dự án. Tôi ăn trưa vào buổi trưa và quay lại làm việc cho đến 5 giờ chiều. sau giờ làm việc tôi thích thư giãn bằng cách chơi bóng đá với bạn bè đó là một cách tuyệt vời để luôn năng động và vui vẻ", "question_vi": "Một người đàn ông đang nói về thói quen hàng ngày của mình. Anh ấy làm gì sau giờ làm việc?", "answer_guess": true, "extra": ["Watches TV", "Goes swimming"], "audio": "data/Aptis_Listening_P1_De02/audio/q38.mp3"}, {"id": 39, "question": "A man and a woman are talking about shopping. What does the man buy in shops?", "options": [{"key": "A", "text": "Furniture"}, {"key": "B", "text": "Cups"}, {"key": "C", "text": "Clothes"}], "answer": "C", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q090.mp3", "transcript": "Do you usually shop online sometimes but not for everything I bought some furniture online last month and it was fine what about things like cups and kitchen items I usually order those online too the only things I prefer to buy in shops are closed because I like to try them on first", "translation": "Đôi khi bạn có thường mua sắm trực tuyến nhưng không phải tất cả mọi thứ. Tôi đã mua một số đồ nội thất trực tuyến vào tháng trước và những thứ như cốc và đồ dùng nhà bếp thì không sao. Tôi cũng thường đặt hàng trực tuyến những thứ duy nhất tôi thích mua ở các cửa hàng đều đóng cửa vì tôi muốn thử chúng trước", "question_vi": "Một người đàn ông và một người phụ nữ đang nói chuyện về việc mua sắm. Người đàn ông mua gì ở cửa hàng?", "answer_guess": true, "extra": ["Books", "Food"], "audio": "data/Aptis_Listening_P1_De02/audio/q39.mp3"}, {"id": 40, "question": "A man and a woman are talking about driving. Why did the man learn to drive?", "options": [{"key": "A", "text": "He has to travel to work"}, {"key": "B", "text": "He lost his driving license"}, {"key": "C", "text": "He bought a new car"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q058.mp3", "transcript": "Hey Sarah I've got some news I'm moving to a new place oh really that sounds exciting where's your new place it's actually pretty far from my workplace and the public transport there isn't great so I've been thinking I need to learn how to drive yeah that makes sense it's hard to rely on public transport if it's not reliable have you ever driven before not really I've always used buses and trains but now it looks like I don't have a choice I need to get a license you'll get the hang of it driving will definitely make your commute easier are you planning to take lessons soon yeah I'm going to sign up for a driving school next week hopefully I can get it done quickly", "translation": "Này Sarah Tôi có một số tin tức Tôi sắp chuyển đến một nơi mới ồ, điều đó thật thú vị. Nơi ở mới của bạn ở đâu, nó thực sự khá xa nơi làm việc của tôi và phương tiện giao thông công cộng ở đó không tốt nên tôi đang nghĩ mình cần học cách lái xe vâng, điều đó hợp lý nếu nó không đáng tin cậy thì thật khó để dựa vào phương tiện công cộng nếu nó không đáng tin cậy. Bạn đã từng lái xe trước đây chưa? Tôi luôn sử dụng xe buýt và xe lửa nhưng bây giờ có vẻ như tôi không có lựa chọn nào khác. Tôi cần phải có bằng lái, bạn sẽ quen với nó việc lái xe chắc chắn sẽ giúp việc đi lại của bạn dễ dàng hơn bạn có định đi học sớm không vâng tôi sẽ đăng ký một trường dạy lái xe vào tuần tới hy vọng tôi có thể hoàn thành việc đó nhanh chóng", "question_vi": "Một người đàn ông và một người phụ nữ đang nói chuyện về việc lái xe. Tại sao người đàn ông học lái xe?", "answer_guess": true, "extra": ["He wants to visit his parents", "His friends asked him to"], "audio": "data/Aptis_Listening_P1_De02/audio/q40.mp3"}, {"id": 41, "question": "What time does the party start?", "options": [{"key": "A", "text": "3 o'clock"}, {"key": "B", "text": "4 o'clock"}, {"key": "C", "text": "5 o'clock"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q092.mp3", "transcript": "Hi everyone just a reminder about today's party some guests may arrive around 4:00 and the music will begin at 5:00 however the party itself starts at 3:00 so please try to arrive before then", "translation": "Xin chào mọi người, xin nhắc lại về bữa tiệc hôm nay một số khách có thể đến vào khoảng 4:00 và âm nhạc sẽ bắt đầu lúc 5:00 tuy nhiên bữa tiệc sẽ bắt đầu lúc 3:00 vì vậy vui lòng cố gắng đến trước lúc đó", "question_vi": "Bữa tiệc bắt đầu lúc mấy giờ?", "answer_guess": true, "extra": ["2 o'clock", "6 o'clock"], "audio": "data/Aptis_Listening_P1_De02/audio/q41.mp3"}, {"id": 42, "question": "A man has a new job. How many days does the man have to work?", "options": [{"key": "A", "text": "3 days"}, {"key": "B", "text": "5 days"}, {"key": "C", "text": "6 days"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q093.mp3", "transcript": "I started a new job last week at first I thought I would need to work 6 days a week but that was only during training some of my colleagues work 5 days from Monday to Friday however my schedule is different I only work on Monday Wednesday and Friday so I work 3 days a week", "translation": "Tôi bắt đầu công việc mới vào tuần trước, lúc đầu tôi nghĩ mình sẽ cần phải làm việc 6 ngày một tuần nhưng đó chỉ là trong thời gian đào tạo, một số đồng nghiệp của tôi làm việc 5 ngày từ thứ Hai đến thứ Sáu tuy nhiên lịch trình của tôi khác. Tôi chỉ làm việc vào thứ Hai, thứ Tư và thứ Sáu nên tôi làm việc 3 ngày một tuần", "question_vi": "Một người đàn ông có một công việc mới. Người đàn ông phải làm việc bao nhiêu ngày?", "answer_guess": true, "extra": ["4 days", "2 days"], "audio": "data/Aptis_Listening_P1_De02/audio/q42.mp3"}, {"id": 43, "question": "Why can't he (the repairman) do the job today?", "options": [{"key": "A", "text": "He is going to the cinema"}, {"key": "B", "text": "He is tired"}, {"key": "C", "text": "He has another appointment"}], "answer": "C", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q094.mp3", "transcript": "Can you come and fix the washing machine today I'm afraid I can't I was planning to go to the cinema this evening but that's not the problem are you too tired to work today no not at all the reason is that I already have another appointment this afternoon I can come tomorrow instead", "translation": "Hôm nay bạn có thể đến sửa máy giặt không. Tôi e là không thể. Tôi định đi xem phim tối nay nhưng đó không phải là vấn đề, hôm nay bạn quá mệt để làm việc, không, lý do là tôi đã có cuộc hẹn khác vào chiều nay. Thay vào đó, tôi có thể đến vào ngày mai", "question_vi": "Tại sao hôm nay anh ấy (thợ sửa chữa) không thể làm việc đó?", "answer_guess": true, "extra": ["He is ill", "His car broke down"], "audio": "data/Aptis_Listening_P1_De02/audio/q43.mp3"}, {"id": 44, "question": "What is the man going to do?", "options": [{"key": "A", "text": "Work overtime"}, {"key": "B", "text": "Get something to eat"}, {"key": "C", "text": "Watch a movie"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q095.mp3", "transcript": "Are you staying late at the office today know I finished all my work earlier than expected great are you going to watch a movie then not today I'm really hungry so I'm going to get something to eat before I go home", "translation": "Hôm nay bạn có ở lại văn phòng muộn không biết tôi đã hoàn thành công việc sớm hơn dự kiến. Tuyệt vời, bạn định xem phim chứ không phải hôm nay. Tôi rất đói nên tôi sẽ đi ăn gì đó trước khi về nhà.", "question_vi": "Người đàn ông sẽ làm gì?", "answer_guess": true, "extra": ["Go to the gym", "Visit a friend"], "audio": "data/Aptis_Listening_P1_De02/audio/q44.mp3"}, {"id": 45, "question": "What is the new health center next to?", "options": [{"key": "A", "text": "A supermarket"}, {"key": "B", "text": "A school"}, {"key": "C", "text": "A train station"}], "answer": "C", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q096.mp3", "transcript": "The new Health Center is easy to find some people think it's next to the supermarket because that's where the old Clinic used to be others say it's near the school but that's not correct either the new building is right next to the train station opposite the town library", "translation": "Trung tâm Y tế mới rất dễ tìm thấy một số người nghĩ rằng nó nằm cạnh siêu thị vì đó là nơi Phòng khám cũ từng là nơi những người khác nói rằng nó gần trường học nhưng điều đó không đúng vì tòa nhà mới nằm ngay cạnh ga xe lửa đối diện thư viện thị trấn", "question_vi": "Trung tâm y tế mới bên cạnh là gì?", "answer_guess": true, "extra": ["A hospital", "A park"], "audio": "data/Aptis_Listening_P1_De02/audio/q45.mp3"}, {"id": 46, "question": "A father phoning his children. What will he buy?", "options": [{"key": "A", "text": "Tea"}, {"key": "B", "text": "Coffee"}, {"key": "C", "text": "Coke"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q097.mp3", "transcript": "Hi kids I'm on my way home from work I know we're out of coffee but I bought some yesterday so we don't need any more I was also thinking about getting some Coke but there's still a bottle in the fridge we have completely run out of tea so I'll stop at the shop and buy some on the way home", "translation": "Xin chào các bạn Tôi đang trên đường đi làm về Tôi biết chúng ta đã hết cà phê nhưng hôm qua tôi đã mua một ít nên chúng ta không cần nữa Tôi cũng đang nghĩ đến việc mua một ít Coke nhưng vẫn còn một chai trong tủ lạnh, chúng tôi đã hết trà nên tôi sẽ dừng lại ở cửa hàng và mua một ít trên đường về nhà", "question_vi": "Một người cha đang gọi điện cho con mình. Anh ấy sẽ mua gì?", "answer_guess": true, "extra": ["Milk", "Juice"], "audio": "data/Aptis_Listening_P1_De02/audio/q46.mp3"}, {"id": 47, "question": "A girl calling a client about their work time. When will the shop open on Monday?", "options": [{"key": "A", "text": "8.30 p.m"}, {"key": "B", "text": "8.30 a.m"}, {"key": "C", "text": "7.30 a.m"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q098.mp3", "transcript": "Hello I'm calling to confirm our opening hours for next week on Saturday the shop opens at 7:30 a.m. and closes early in the afternoon some customers think we open at 8:30 p.m. on Monday the shop will open at 8:30 a.m. as usual", "translation": "Xin chào, tôi gọi điện để xác nhận giờ mở cửa của chúng tôi vào Thứ Bảy tuần tới, cửa hàng mở cửa lúc 7:30 sáng và đóng cửa sớm vào buổi chiều, một số khách hàng nghĩ rằng chúng tôi mở cửa lúc 8:30 tối. Thứ Hai quán sẽ mở cửa lúc 8h30 sáng như thường lệ", "question_vi": "Một cô gái gọi cho khách hàng về thời gian làm việc của họ. Khi nào cửa hàng sẽ mở cửa vào thứ Hai?", "answer_guess": true, "extra": ["9.00 a.m", "7.30 p.m"], "audio": "data/Aptis_Listening_P1_De02/audio/q47.mp3"}, {"id": 48, "question": "A girl calls her friend about a party. What will she take there?", "options": [{"key": "A", "text": "Games"}, {"key": "B", "text": "Cards"}, {"key": "C", "text": "Food"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q099.mp3", "transcript": "Hi Emma I'm really looking forward to the party tonight I was thinking about bringing some food but I heard there will already be plenty I also found a pack of cards at home but I don't think we'll need them instead I'm going to bring a few party games so everyone can join in and have fun", "translation": "Xin chào Emma. Tôi rất mong chờ bữa tiệc tối nay. Tôi đang nghĩ đến việc mang theo một ít đồ ăn nhưng tôi nghe nói sẽ có rất nhiều. Tôi cũng tìm thấy một bộ bài ở nhà nhưng tôi không nghĩ chúng ta sẽ cần chúng. Thay vào đó, tôi sẽ mang theo một vài trò chơi tiệc tùng để mọi người có thể tham gia và vui chơi", "question_vi": "Một cô gái gọi cho bạn mình về một bữa tiệc. Cô ấy sẽ mang gì tới đó?", "answer_guess": true, "extra": ["Drinks", "Music"], "audio": "data/Aptis_Listening_P1_De02/audio/q48.mp3"}, {"id": 49, "question": "David and Anna are waiting for the bus together. Which bus stops near the house?", "options": [{"key": "A", "text": "Number one"}, {"key": "B", "text": "Number eight"}, {"key": "C", "text": "Number seven"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-02-q100.mp3", "transcript": "Do we need the number one bus to get home know that one goes to the town center what about the number seven it stops near the sports center the bus that stops near our house is the number 8", "translation": "Chúng ta có cần xe buýt số một để về nhà không? Xe buýt dừng gần nhà chúng ta là số 7, nó dừng gần trung tâm thể thao, xe buýt dừng gần nhà chúng ta là số 8", "question_vi": "David và Anna đang cùng nhau đợi xe buýt. Xe buýt nào dừng gần nhà?", "answer_guess": true, "extra": ["Number six", "Number ten"], "audio": "data/Aptis_Listening_P1_De02/audio/q49.mp3"}]};
